solutions.naive:
class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        letters = list(magazine)
        for ch in ransomNote:
            if ch not in letters:
                return False
            letters.remove(ch)
        return True

solutions.better:
from collections import Counter

class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        available = Counter(magazine)
        for ch in ransomNote:
            if available[ch] == 0:
                return False
            available[ch] -= 1
        return True

solutions.optimal:
class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        counts = [0] * 26
        for ch in magazine:
            counts[ord(ch) - ord('a')] += 1
        for ch in ransomNote:
            idx = ord(ch) - ord('a')
            counts[idx] -= 1
            if counts[idx] < 0:
                return False
        return True

